# Let's manually examine the differences
inputs = ['bkwauj', 'vk', 'vvww', 'vfceyd', 'jdigk']
outputs = ['beicexeuj', 'vei', 'vvcexcex', 'vfceyd', 'jdigei']

print("Analyzing differences:")
for i in range(len(inputs)):
    inp = inputs[i]
    out = outputs[i]
    print(f"{i}: '{inp}' -> '{out}'")

    # Find where they differ
    min_len = min(len(inp), len(out))
    diff_pos = -1
    for j in range(min_len):
        if inp[j] != out[j]:
            diff_pos = j
            break

    if diff_pos == -1:
        if len(inp) != len(out):
            diff_pos = min_len
    if diff_pos != -1:
        print(f"  First difference at position {diff_pos}")
        if diff_pos < len(inp) and diff_pos < len(out):
            print(f"  Character changed: '{inp[diff_pos]}' -> '{out[diff_pos]}'")
        elif diff_pos >= len(inp):
            print(f"  Extra characters added at end: '{out[diff_pos:]}'")
        else:
            print(f"  Extra characters removed at end")
    print()

